export type DamageType = 'pothole' | 'crack';

export type SeverityLevel = 'Low' | 'Medium' | 'High';

export type DetectionEngineMode = 'gemini' | 'stub' | 'yolo';

export interface BoundingBox {
  /** Normalized left coordinate [0..1] */
  x: number;
  /** Normalized top coordinate [0..1] */
  y: number;
  /** Normalized width [0..1] */
  width: number;
  /** Normalized height [0..1] */
  height: number;
}

export interface RoadDetection {
  id: string;
  type: DamageType;
  confidence: number;
  severity: SeverityLevel;
  bbox: BoundingBox;
  /** True strictly when generated by the Prototype Stub (never masquerades as real AI) */
  isSimulated: boolean;
}

export interface DetectionModelInfo {
  engine: DetectionEngineMode;
  modelName: string;
  isSimulated: boolean;
  inferenceMs: number;
}

export interface DetectionResultPayload {
  detections: RoadDetection[];
  modelInfo: DetectionModelInfo;
}

export interface GpsCoordinate {
  latitude: number;
  longitude: number;
  accuracyMeters: number | null;
  capturedAt: number;
}

export interface ConfirmedDetectionRecord {
  id: string;
  type: DamageType;
  confidence: number;
  severity: SeverityLevel;
  timestamp: string;
  latitude: number | null;
  longitude: number | null;
  accuracyMeters: number | null;
  isSimulated: boolean;
  engineName: string;
  thumbnailDataUrl?: string;
}

export interface ScanSessionSummary {
  sessionId: string;
  startedAt: string;
  endedAt: string;
  engineMode: DetectionEngineMode;
  totalPotholes: number;
  totalCracks: number;
  highestSeverity: SeverityLevel | 'None';
  records: ConfirmedDetectionRecord[];
}
